class NotConnectedException(Exception):
    """ Raises when connect wasn't used before authenticate the connection. """


class DcapVersionNotSupported(Exception):
    """ Raises when provided CU version is not supported. """


class IncorrectLoginCredentials(Exception):
    """ Raises when response type from login is invalid. Credentials are wrong. """


class AuthenticationFailed(Exception):
    """ Raises when authentication to security API failed. """


class SoftwareVersionInconsistent(Exception):
    """Raises when gnb installed is on different software version on VMS. """


class ParameterNotProvided(Exception):
    """Raises when required parameter is not provided"""


class FileNotFound(Exception):
    pass


class WrongApiResponseStatus(Exception):
    pass


class TimeoutException(Exception):
    pass


class DenialApiResponse(Exception):
    pass
